INSERT INTO lessons (concept_id, title, content_html, creator_id, created_at, category, difficulty, estimated_time, points, grade_levels, description, objectives, prerequisites, tags)
SELECT (SELECT id FROM concept_id_cte),
       'St. Kitts & Nevis Science - Marine Ecosystems - Coral reefs, mangroves (Grade 7)',
       '<h2>Introduction to Coral reefs, mangroves</h2><p>This lesson explores Coral reefs, mangroves in the context of St. Kitts & Nevis Science.</p><p>Key points include: Coral reefs, mangroves, Conservation efforts.</p>',
       (SELECT id FROM teach_user_id_cte),
       NOW(),
       'Core Subject',
       'medium',
       45,
       60,
       'Grade 7',
       'An in-depth lesson on Coral reefs, mangroves focusing on St. Kitts & Nevis for Grade 7 students.',
       'Understand Coral reefs, mangroves, identify related concepts, and apply knowledge to St. Kitts & Nevis-specific scenarios.',
       'Basic understanding of science. ',
       'st.kitts&nevis,science,marineecosystems,coralreefs,mangroves,grade7,medium'
ON CONFLICT (title) DO NOTHING;


