     subject_id_cte AS (SELECT id FROM subjects WHERE name = 'Mathematics'),
     curriculum_subject_id_cte AS (
         SELECT cs.id FROM curriculum_subjects cs
         JOIN country_id_cte c ON cs.country_id = c.id
         JOIN subject_id_cte s ON cs.subject_id = s.id
         WHERE cs.grade_level = 12
     ),
     school_year_id_cte AS (SELECT id FROM school_years WHERE country_id = (SELECT id FROM country_id_cte) AND year_label = 'Grade 12'),
     term_id_cte AS (SELECT id FROM terms WHERE school_year_id = (SELECT id FROM school_year_id_cte) AND term_number = 1 LIMIT 1),
     topic_id_cte AS (
         SELECT id FROM topics
         WHERE curriculum_subject_id = (SELECT id FROM curriculum_subject_id_cte)
           AND term_id = (SELECT id FROM term_id_cte)
           AND title = 'Statistics & Probability'
     ),
     concept_id_cte AS (
         SELECT id FROM concepts
         WHERE topic_id = (SELECT id FROM topic_id_cte) AND title = 'Basic probability'
     )
INSERT INTO lessons (concept_id, title, content_html, creator_id, created_at, category, difficulty, estimated_time, points, grade_levels, description, objectives, prerequisites, tags)
SELECT (SELECT id FROM concept_id_cte),
       'St. Kitts & Nevis Mathematics - Statistics & Probability - Basic probability (Grade 12)',
       '<h2>Introduction to Basic probability</h2><p>This lesson explores Basic probability in the context of St. Kitts & Nevis Mathematics.</p><p>Key points include: Data representation, Basic probability.</p>',
       (SELECT id FROM teach_user_id_cte),
       NOW(),
       'Core Subject',
       'advanced',
       30,
       50,
       'Grade 12',
       'An in-depth lesson on Basic probability focusing on St. Kitts & Nevis for Grade 12 students.',
       'Understand Basic probability, identify related concepts, and apply knowledge to St. Kitts & Nevis-specific scenarios.',
       'Basic understanding of mathematics. ',
       'st.kitts&nevis,mathematics,statistics&probability,basicprobability,grade12,advanced'
ON CONFLICT (title) DO NOTHING;


WITH lesson_id_cte AS (SELECT id FROM lessons WHERE title = 'St. Kitts & Nevis Mathematics - Statistics & Probability - Basic probability (Grade 12)')
INSERT INTO quizzes (lesson_id, question, question_type, options, correct_answer, explanation, points, difficulty, time_limit, image_url, tags)
SELECT (SELECT id FROM lesson_id_cte),
       'What is a key aspect of Basic probability in St. Kitts & Nevis?',
       'mc_single',
       '["Option A for Basic probability", "Option B for Basic probability (correct)", "Option C for Basic probability", "Option D for Basic probability"]',
       'Option B for Basic probability (correct)',
       'Option B is correct because it directly relates to the core idea of Basic probability as discussed in the lesson.',
       10,
       'hard',
       60,
       '',
       'st.kitts&nevis,mathematics,quiz,advanced'
ON CONFLICT DO NOTHING; 


