     subject_id_cte AS (SELECT id FROM subjects WHERE name = 'Science'),
     curriculum_subject_id_cte AS (
         SELECT cs.id FROM curriculum_subjects cs
         JOIN country_id_cte c ON cs.country_id = c.id
         JOIN subject_id_cte s ON cs.subject_id = s.id
         WHERE cs.grade_level = 11
     ),
     school_year_id_cte AS (SELECT id FROM school_years WHERE country_id = (SELECT id FROM country_id_cte) AND year_label = 'Grade 11'),
     term_id_cte AS (SELECT id FROM terms WHERE school_year_id = (SELECT id FROM school_year_id_cte) AND term_number = 1 LIMIT 1),
     topic_id_cte AS (
         SELECT id FROM topics
         WHERE curriculum_subject_id = (SELECT id FROM curriculum_subject_id_cte)
           AND term_id = (SELECT id FROM term_id_cte)
           AND title = 'Geothermal Energy'
     ),
     concept_id_cte AS (
         SELECT id FROM concepts
         WHERE topic_id = (SELECT id FROM topic_id_cte) AND title = 'Harnessing natural heat'
     )
INSERT INTO lessons (concept_id, title, content_html, creator_id, created_at, category, difficulty, estimated_time, points, grade_levels, description, objectives, prerequisites, tags)
SELECT (SELECT id FROM concept_id_cte),
       'Dominica Science - Geothermal Energy - Harnessing natural heat (Grade 11)',
       '<h2>Introduction to Harnessing natural heat</h2><p>This lesson explores Harnessing natural heat in the context of Dominica Science.</p><p>Key points include: Harnessing natural heat, Benefits and challenges.</p>',
       (SELECT id FROM teach_user_id_cte),
       NOW(),
       'Core Subject',
       'advanced',
       30,
       60,
       'Grade 11',
       'An in-depth lesson on Harnessing natural heat focusing on Dominica for Grade 11 students.',
       'Understand Harnessing natural heat, identify related concepts, and apply knowledge to Dominica-specific scenarios.',
       'Basic understanding of science. ',
       'dominica,science,geothermalenergy,harnessingnaturalheat,grade11,advanced'
ON CONFLICT (title) DO NOTHING;


WITH lesson_id_cte AS (SELECT id FROM lessons WHERE title = 'Dominica Science - Geothermal Energy - Harnessing natural heat (Grade 11)')
INSERT INTO quizzes (lesson_id, question, question_type, options, correct_answer, explanation, points, difficulty, time_limit, image_url, tags)
SELECT (SELECT id FROM lesson_id_cte),
       'What is a key aspect of Harnessing natural heat in Dominica?',
       'mc_single',
       '["Option A for Harnessing natural heat", "Option B for Harnessing natural heat (correct)", "Option C for Harnessing natural heat", "Option D for Harnessing natural heat"]',
       'Option B for Harnessing natural heat (correct)',
       'Option B is correct because it directly relates to the core idea of Harnessing natural heat as discussed in the lesson.',
       15,
       'hard',
       60,
       '',
       'dominica,science,quiz,advanced'
ON CONFLICT DO NOTHING; 


