WITH country_id_cte AS (SELECT id FROM countries WHERE name = 'Dominica'),
     subject_id_cte AS (SELECT id FROM subjects WHERE name = 'Mathematics'),
     curriculum_subject_id_cte AS (
         SELECT cs.id FROM curriculum_subjects cs
         JOIN country_id_cte c ON cs.country_id = c.id
         JOIN subject_id_cte s ON cs.subject_id = s.id
         WHERE cs.grade_level = 7
     ),
     school_year_id_cte AS (SELECT id FROM school_years WHERE country_id = (SELECT id FROM country_id_cte) AND year_label = 'Grade 7'),
     term_id_cte AS (SELECT id FROM terms WHERE school_year_id = (SELECT id FROM school_year_id_cte) AND term_number = 1 LIMIT 1)
